/** Cold-process barriers around the real asynchronous native landing-foot journal. */
public final class ArmLandingRecoveryChecks {
    private static final BlockPos ROOT=new BlockPos(15,100,0),HOME=ROOT.down(2);
    private static int stage,ticks;private static boolean resumed,bound;private static BlockPos source;private static NBTTagCompound expected;private static TransferCheckpoint checkpoint;
    public static boolean active(){return System.getProperty("vandorlabs.armRecoveryPhase","").contains("landing-attach-");}
    static boolean paused(){return !resumed;}
    private static void require(boolean ok,String message){if(!ok)throw new IllegalStateException("Native landing cold stage="+stage+" tick="+ticks+": "+message);}
    private static GearTileEntity root(WorldServer world){TileEntity tile=world.getTileEntity(ROOT);require(tile instanceof GearTileEntity,"native arm root present");return (GearTileEntity)tile;}
    private static File proof(WorldServer world){return new File(world.getSaveHandler().getWorldDirectory(),"landing-attach-proof.nbt");}
    private static int feet(){return expected==null?1:expected.getInteger("Feet");}
    private static BlockPos home(int n){return BlockPos.fromLong(expected.getTagList("Sources",10).getCompoundTagAt(n).getLong("Home"));}
    private static Collection<net.minecraft.world.chunk.Chunk> chunks(WorldServer world){Set<net.minecraft.world.chunk.Chunk> chunks=new LinkedHashSet<>();chunks.add(world.getChunkFromBlockCoords(ROOT));NBTTagList sources=expected.getTagList("Sources",10);for(int n=0;n<sources.tagCount();n++){chunks.add(world.getChunkFromBlockCoords(home(n)));chunks.add(world.getChunkFromBlockCoords(BlockPos.fromLong(sources.getCompoundTagAt(n).getLong("Pos"))));}return chunks;}
    private static void verifyOriginals(WorldServer world){NBTTagList sources=expected.getTagList("Sources",10);for(int n=0;n<sources.tagCount();n++){NBTTagCompound cell=sources.getCompoundTagAt(n);BlockPos at=BlockPos.fromLong(cell.getLong("Pos"));require(world.getBlockState(at)==NBTUtil.readBlockState(cell.getCompoundTag("State")),"rollback native source state exact "+n);require(world.getTileEntity(at)!=null&&world.getTileEntity(at).writeToNBT(new NBTTagCompound()).equals(cell.getCompoundTag("Tile")),"rollback native source NBT and opaque capabilities exact "+n);require(world.isAirBlock(home(n)),"rollback construction cell empty "+n);}}

    public static boolean run(WorldServer world,EntityPlayerMP actor,String phase)throws Exception{
        require(++ticks<1200,"bounded journal preparation/publication "+ArmTransactions.diagnostic(world,ROOT)+" root="+(world.getTileEntity(ROOT) instanceof GearTileEntity?root(world).progress()+" target="+root(world).target()+" operational="+root(world).isOperational()+" error="+root(world).error():"missing"));ArmEndpointLandingCaps.enable();for(int x:new int[]{-4,4})for(int z:new int[]{-4,4})world.getChunkFromBlockCoords(ROOT.add(x,0,z));
        if(phase.startsWith("verify")){
            if(expected==null){try(DataInputStream input=new DataInputStream(new java.util.zip.GZIPInputStream(new FileInputStream(proof(world))))){expected=CompressedStreamTools.read(input,new NBTSizeTracker(1024*1024));}source=BlockPos.fromLong(expected.getLong("Source"));}
            if(ArmTransactions.locked(world,ROOT))return false;GearTileEntity arm=root(world);
            if(phase.startsWith("verify2")){verifyBound(world,arm);System.out.println("[vandorlabs] arm-durable-recovery PASS "+phase+" second cold load native landing owner exactly once physical ForgeCaps");return true;}
            if(stage==0){require(arm.progress()==0&&arm.target()&&!arm.isLandingAssembly()&&arm.payload()==null&&!arm.middleHinge(),"rollback restores active generic arm and pending requested target with legacy Base hinge default");verifyOriginals(world);arm.operator(actor);ArmActiveLanding.testObserver=message->System.out.println("[vandorlabs] landing-cold trace "+message);ArmActiveLanding.testBound=landing->{require(landing.progress()==0&&landing.isLandingAssembly(),"retry binds while active");bound=true;};resumed=true;stage=1;return false;}
            require(arm.target(),"pending retry remains requested progress="+arm.progress()+" error="+arm.error());if(arm.progress()!=1||!arm.isLandingAssembly())return false;require(bound,"retry traversed real native binding");verifyBound(world,arm);if(checkpoint==null)checkpoint=new TransferCheckpoint(world,chunks(world));if(!checkpoint.step())return false;checkpoint.close();checkpoint=null;ArmActiveLanding.testBound=null;System.out.println("[vandorlabs] arm-durable-recovery PASS "+phase+" killed process rollback then actual asynchronous retry native landing owner exactly once");return true;
        }
        if(stage==0){
            physicalFactories(world);
            for(BlockPos at:BlockPos.getAllInBox(ROOT.add(-4,-4,-4),ROOT.add(4,3,4))){world.removeTileEntity(at);world.setBlockToAir(at);}world.setBlockState(ROOT.up(),Blocks.STONE.getDefaultState(),2);actor.setHeldItem(EnumHand.MAIN_HAND,new ItemStack(GearRegistry.GEAR_SWING_ARM,2));
            boolean group=phase.contains("-group-"),large=phase.contains("-large-");GearBlock armBlock=large?GearRegistry.LARGE_GEAR_SWING_ARM:GearRegistry.GEAR_SWING_ARM;for(int column:group?new int[]{0,2}:new int[]{0}){world.setBlockState(ROOT.east(column).up(),Blocks.STONE.getDefaultState(),2);actor.setHeldItem(EnumHand.MAIN_HAND,new ItemStack(armBlock,2));for(int n=0;n<2;n++)require(actor.getHeldItemMainhand().onItemUse(actor,world,ROOT.east(column).up(1-n),EnumHand.MAIN_HAND,EnumFacing.DOWN,.5F,.5F,.5F)==EnumActionResult.SUCCESS,"ordinary supported column placement");GearTileEntity part=(GearTileEntity)world.getTileEntity(ROOT.east(column));part.operator(actor);require(part.rebuild(),"bare column forms");NBTTagCompound settings=part.settings();settings.setBoolean("RotatePayload",true);settings.setBoolean("JoinArms",group);settings.setInteger("JoinRange",3);part.configure(settings);}GearTileEntity arm=root(world);require(arm.rebuild()&&arm.columns().size()==(group?2:1),"initial bare group forms");arm.captureProgress(0);arm.target(true);ArmPayload.Endpoint endpoint=ArmPayload.endpoint(arm,0);require(endpoint!=null,"aligned active grid endpoint");source=endpoint.placed(HOME);require((source.getZ()>>4)!=(HOME.getZ()>>4),"source and construction cell straddle chunk boundary");
            GearBlock foot=large?GearRegistry.LARGE_LANDING_WHEEL:GearRegistry.LANDING_PLATE;ItemBlock item=(ItemBlock)Item.getItemFromBlock(foot);expected=new NBTTagCompound();expected.setInteger("Feet",large||group?4:1);expected.setBoolean("Large",large);expected.setLong("Source",source.toLong());List<BlockPos> nativeCells=new ArrayList<>();if(large){NBTTagCompound template=new NBTTagCompound();template.setString("id",TileEntity.getKey(GearTileEntity.class).toString());template.setString("ArmMountDirection",EnumFacing.DOWN.name());net.minecraft.block.state.IBlockState canonical=foot.getDefaultState().withProperty(GearBlock.FACING,world.getBlockState(ROOT).getValue(GearBlock.FACING));net.minecraft.block.state.IBlockState posed=endpoint.placedState(new com.vandorlabs.vehicle.VehicleStructure.Cell(HOME,canonical,template));require(posed!=null,"Large Wheel frame maps to active endpoint");try(ArmFootComponentFrame.Placement placement=ArmFootComponentFrame.placing(endpoint.mappedFacing(EnumFacing.DOWN),posed.getValue(GearBlock.FACING))){require(item.placeBlockAt(new ItemStack(item),actor,world,source,EnumFacing.UP,.5F,.5F,.5F,posed),"native four-cell Wheel placed in posed frame");}nativeCells.addAll(foot.componentCells(world,source));require(foot.componentIntact(world,source),"initial four-cell native component intact");}else for(int n=0;n<feet();n++){BlockPos at=source.east(n);require(item.placeBlockAt(new ItemStack(item),actor,world,at,EnumFacing.UP,.5F,.5F,.5F,foot.getDefaultState()),"native Plate placed at active socket/group");nativeCells.add(at);}NBTTagList sources=new NBTTagList();for(BlockPos at:nativeCells){NBTTagCompound cell=new NBTTagCompound();cell.setLong("Pos",at.toLong());cell.setLong("Home",endpoint.construction(at).toLong());cell.setTag("State",NBTUtil.writeBlockState(new NBTTagCompound(),world.getBlockState(at)));cell.setTag("Tile",world.getTileEntity(at).writeToNBT(new NBTTagCompound()));sources.appendTag(cell);}expected.setTag("Sources",sources);expected.setTag("Tile",sources.getCompoundTagAt(0).getCompoundTag("Tile"));ByteArrayOutputStream encoded=new ByteArrayOutputStream();CompressedStreamTools.writeCompressed(expected,encoded);try(FileOutputStream output=new FileOutputStream(proof(world))){output.write(encoded.toByteArray());output.getFD().sync();}JournalFiles.syncDirectory(proof(world).toPath().getParent());arm.markDirty();checkpoint=new TransferCheckpoint(world,chunks(world));stage=1;return false;
        }
        if(stage==1){if(!checkpoint.step())return false;checkpoint.close();checkpoint=null;ArmTransactions.testFault=point->{if(!point.equals(phase.endsWith("prepared")?"prepared":"attach-foot"))return;try{if(phase.endsWith("partial"))try(TransferCheckpoint partial=new TransferCheckpoint(world,Collections.singleton(world.getChunkFromBlockCoords(HOME)))){long until=System.nanoTime()+15000000000L;while(!partial.step()){if(System.nanoTime()>until)throw new IllegalStateException("Landing partial save timeout");Thread.sleep(5);}}File marker=new File(world.getSaveHandler().getWorldDirectory(),"arm-crash-ready.txt");try(FileOutputStream output=new FileOutputStream(marker)){output.write(java.lang.management.ManagementFactory.getRuntimeMXBean().getName().split("@")[0].getBytes(java.nio.charset.StandardCharsets.US_ASCII));output.getFD().sync();}System.out.println("[vandorlabs] arm-durable-crash "+phase+" real native landing journal durable");System.out.flush();new java.util.concurrent.CountDownLatch(1).await();}catch(Exception failure){throw new IllegalStateException(failure);}};stage=2;}
        root(world).preparePayloadMotion();return false;
    }
    private static void verifyBound(WorldServer world,GearTileEntity arm){require(arm.progress()==1&&arm.target()&&arm.isLandingAssembly()&&arm.payload()==null&&arm.assembly().feet().size()==feet(),"one formed landing owner at deployed endpoint");if(expected.getBoolean("Large"))require(arm.assembly().kind()==com.vandorlabs.gear.core.GearTopology.FootKind.WHEEL&&GearRegistry.LARGE_LANDING_WHEEL.componentIntact(world,HOME),"cold four-cell wheel retains exact native component");NBTTagList sources=expected.getTagList("Sources",10);for(int n=0;n<feet();n++){require(world.isAirBlock(BlockPos.fromLong(sources.getCompoundTagAt(n).getLong("Pos"))),"old native source retired "+n);TileEntity raw=world.getTileEntity(home(n));require(raw instanceof GearTileEntity&&((GearTileEntity)raw).loadedController()==arm&&((GearTileEntity)raw).mountDirection()==arm.mountDirection(),"native foot bound to original mounting controller "+n);if(expected.getBoolean("Large"))require(((GearTileEntity)raw).componentFrame()==arm.mountDirection(),"cold native component frame retained "+n);require(raw.writeToNBT(new NBTTagCompound()).getCompoundTag("ForgeCaps").equals(sources.getCompoundTagAt(n).getCompoundTag("Tile").getCompoundTag("ForgeCaps")),"opaque physical capability bytes retained "+n);}}
    private static void physicalFactories(WorldServer world){
        BlockPos chest=ROOT.south(3),sign=ROOT.south(4);world.setBlockState(chest,Blocks.CHEST.getDefaultState(),2);((net.minecraft.inventory.IInventory)world.getTileEntity(chest)).setInventorySlotContents(0,new ItemStack(net.minecraft.init.Items.DIAMOND,7));world.setBlockState(sign.down(),Blocks.STONE.getDefaultState(),2);world.setBlockState(sign,Blocks.STANDING_SIGN.getDefaultState(),2);((net.minecraft.tileentity.TileEntitySign)world.getTileEntity(sign)).signText[0]=new net.minecraft.util.text.TextComponentString("Physical factory context");
        for(BlockPos pos:new BlockPos[]{chest,sign}){TileEntity original=world.getTileEntity(pos);NBTTagCompound data=original.writeToNBT(new NBTTagCompound());require(data.getCompoundTag("ForgeCaps").getCompoundTag(ArmEndpointLandingCaps.KEY.toString()).getBoolean("RequirePhysicalWorld"),"vanilla factory probe requires physical context");TileEntity copy=com.vandorlabs.copier.PhysicalTileFactory.create(world,world.getBlockState(pos),data);require(copy.getWorld()==world&&copy.getPos().equals(pos)&&copy.writeToNBT(new NBTTagCompound()).equals(data)&&world.getTileEntity(pos)==original,"vanilla chest/sign physical factory exact own fields and opaque caps without publication");world.removeTileEntity(pos);world.setBlockState(pos,Blocks.AIR.getDefaultState(),2);}
        world.setBlockState(sign.down(),Blocks.AIR.getDefaultState(),2);System.out.println("[vandorlabs] landing-physical-factory PASS vanilla chest/sign world and position available during capability deserialization exact opaque fields noonLoad");
    }
    private ArmLandingRecoveryChecks(){}
}
